class Commando < Formula
  desc "Colorful TUI that turns a command's man page into a form for its options"
  homepage "https://github.com/lonedevel/commando"
  license "Apache-2.0"

  head do
    url "https://github.com/lonedevel/commando.git", branch: "main"
    depends_on "go" => :build
  end

  # Generated by scripts/update-formula.sh from the release's checksums.txt.
  on_macos do
    on_arm do
      url "https://github.com/lonedevel/commando/releases/download/v0.14.0/commando_0.14.0_darwin_arm64.tar.gz"
      sha256 "c07a17ca8e568cec98c42f0223772ddc4990e33b753ce272300aa473989e0352"
    end
    on_intel do
      url "https://github.com/lonedevel/commando/releases/download/v0.14.0/commando_0.14.0_darwin_amd64.tar.gz"
      sha256 "db35c54c78300aa3a3edd28c33dde0882fa4ef842b486dc0c641bc08b162886b"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/lonedevel/commando/releases/download/v0.14.0/commando_0.14.0_linux_arm64.tar.gz"
      sha256 "75ff2d56a87a792ee84d4aa9f034552985c657f4ba6ce246f5121a532b602d50"
    end
    on_intel do
      url "https://github.com/lonedevel/commando/releases/download/v0.14.0/commando_0.14.0_linux_amd64.tar.gz"
      sha256 "f6bf5480d7fff0f14119f489a460bff4c6a711107cb505125fc99a4275f16710"
    end
  end

  def install
    if build.head?
      system "go", "build", *std_go_args(ldflags: "-s -w -X main.version=#{version}"), "./cmd/commando"
    else
      bin.install "commando"
    end
  end

  def caveats
    <<~EOS
      To edit the command you're typing with Ctrl-X Ctrl-O, add to your shell config:
        zsh:  eval "$(commando --init zsh)"
        bash: eval "$(commando --init bash)"
        fish: commando --init fish | source
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/commando --version")
    assert_match "bindkey", shell_output("#{bin}/commando --init zsh")

    # Parse a manual without needing a terminal.
    ENV["COMMANDO_CACHE_DIR"] = testpath/"cache"
    output = shell_output("#{bin}/commando --dump --no-cache ls")
    assert_match "\"names\"", output
  end
end
